//! N-101 — `parseANFProgram` refuses a StatefulSmartContract program
//! (declared, or inferred per N-087) any of whose public methods lacks,
//! reorders or alters the scaffolding ANF lowering injects, with the
//! diagnostics shared by all seven tiers. These cases are copied verbatim from
//! conformance/negatives/ir-stateful-scaffold-cases.json; the full corpus is
//! driven through this tier's CLI by
//! conformance/negatives/ir-stateful-scaffold.test.ts.
//!
//! Before: F-107's attack body relabelled StatefulSmartContract made
//! `compile-ir` print 76767b8777, which an attacker's key spends under strict
//! @bsv/sdk Spend, and so did the parentClass-less variant carrying a dead
//! add_data_output.
//!
//! Proves: each case is refused with its shared message and the unmodified
//! stateful-counter golden (with its user code changed) loads. Does not prove
//! cross-tier agreement or anything about the free user code.

const std = @import("std");
const testing = std.testing;
const json = @import("json.zig");
const required_fields = @import("required_fields.zig");

fn expectLoads(src: []const u8) !void {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    _ = try json.parseANFProgram(arena.allocator(), src);
}

fn expectRefused(src: []const u8, want: []const u8) !void {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    if (json.parseANFProgram(arena.allocator(), src)) |_| {
        return error.TestUnexpectedlyAccepted;
    } else |_| {}
    try testing.expectEqualStrings(want, required_fields.lastDiagnostic() orelse "<none>");
}

